    getSession: vi.fn().mockResolvedValue({ data: { session } }),
    onAuthStateChange: vi.fn((nextListener: AuthStateListener) => {
      listener = nextListener;
      return {
        data: {
          subscription: {
            id: 'app-test-subscription',
            callback: nextListener,
            unsubscribe: vi.fn(),
          },
        },
      };
    }),
