    expect(screen.getByText('Deleting your accountâ€¦')).toHaveAttribute('role', 'status');
    expect(fetchMock).toHaveBeenCalledTimes(2);
    expect(fetchMock).toHaveBeenCalledWith(
      `${testApiBaseUrl}/account`,
      expect.objectContaining({ method: 'DELETE' }),
    );

    await act(async () => {
      resolveRequest(apiResponse(200, { data: { status: 'deleted', retainedCricketData: true } }));
    });

    expect(screen.getByText('Account deleted. Clearing this browser sessionâ€¦')).toHaveAttribute(
      'role',
      'status',
