      return;
    }
    await route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify({ data: { consumers } }) });
  });
  await page.route('**/api/v1/admin/api-consumers/17/keys/rotate', async (route) => {
    nextKeyId += 1;
    const previous = consumers[0] as { keys: Array<Record<string, unknown>> };
    const consumer = { ...previous, keys: [
      { ...previous.keys[0], revokedAt: createdAt },
      { id: String(nextKeyId), prefix: rotatedKey.slice(0, 17), createdAt, revokedAt: null },
    ] };
    consumers = [consumer];
    await route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify({ data: { ...consumer, apiKey: rotatedKey } }) });
  });
