import { consumerUsageQuerySchema, consumerUsageResponseSchema } from '@sport-analytics/contracts';
import type { RequestHandler } from 'express';

import type { ActiveConsumer, ApiConsumerRepository } from './api-consumer.repository';

const MAX_RANGE_DAYS = 31;
const DEFAULT_RANGE_DAYS = 7;

function isoDate(value: Date): string {
  return value.toISOString().slice(0, 10);
}

function invalid(response: Parameters<RequestHandler>[1], field: string, message: string): void {
  response.status(400).json({
    error: {
      code: 'VALIDATION_FAILED',
      message: 'The request is invalid.',
      details: [{ code: 'INVALID_FIELD', field, message }],
    },
  });
}

export function createConsumerUsageController(
  repository: ApiConsumerRepository,
  now: () => Date = () => new Date(),
): RequestHandler {
  return (request, response, next) => {
    const parsed = consumerUsageQuerySchema.safeParse(request.query);
    if (!parsed.success) {
      invalid(response, parsed.error.issues[0]?.path.join('.') || 'query', 'Invalid usage query.');
      return;
    }
    const today = new Date(now());
    today.setUTCHours(0, 0, 0, 0);
    const defaultFrom = new Date(today);
    defaultFrom.setUTCDate(defaultFrom.getUTCDate() - (DEFAULT_RANGE_DAYS - 1));
    const from = parsed.data.from ?? isoDate(defaultFrom);
    const to = parsed.data.to ?? isoDate(today);
    const fromDate = new Date(`${from}T00:00:00.000Z`);
    const toDate = new Date(`${to}T00:00:00.000Z`);
    if (
      Number.isNaN(fromDate.getTime()) ||
      isoDate(fromDate) !== from ||
      Number.isNaN(toDate.getTime()) ||
      isoDate(toDate) !== to
    ) {
      invalid(response, 'from', 'Dates must be calendar dates in YYYY-MM-DD format.');
      return;
    }
    const rangeDays = Math.floor((toDate.getTime() - fromDate.getTime()) / 86_400_000) + 1;
    if (rangeDays < 1) {
      invalid(response, 'to', '`to` must be on or after `from`.');
      return;
    }
    if (rangeDays > MAX_RANGE_DAYS) {
      invalid(response, 'to', `Date ranges may not exceed ${MAX_RANGE_DAYS} days.`);
      return;
    }
    const consumer = response.locals.apiConsumer as ActiveConsumer;
    if (!repository.listUsage) {
      next(new Error('Consumer usage repository is unavailable.'));
      return;
    }
    void repository
      .listUsage(consumer.consumerId, { from, to, limit: parsed.data.limit })
      .then((usage) =>
        response.status(200).json(
          consumerUsageResponseSchema.parse({
            data: {
              from,
              to,
              totalRequests: usage.totalRequests,
              quota: {
                limit: consumer.dailyQuota,
                used: Number(
                  response.getHeader('X-Quota-Remaining')
                    ? consumer.dailyQuota - Number(response.getHeader('X-Quota-Remaining'))
                    : 0,
                ),
                remaining: Number(response.getHeader('X-Quota-Remaining') ?? consumer.dailyQuota),
              },
              entries: usage.entries,
            },
          }),
        ),
      )
      .catch(next);
  };
}

import type { ApiConsumer, ApiConsumerIssue } from '@sport-analytics/contracts';
import { createHash } from 'node:crypto';
import type { Pool } from 'pg';

import { executeQuery, getDatabasePool, withTransaction, type QueryExecutor } from '../../database';

interface ConsumerRow {
  id: string;
  name: string;
  rateLimitPerMinute: number;
  dailyQuota: number;
  createdAt: Date;
}

interface KeyRow {
  id: string;
  consumerId: string;
  prefix: string;
  createdAt: Date;
  revokedAt: Date | null;
}

export interface ActiveConsumer {
  consumerId: string;
  keyId?: string;
  rateLimitPerMinute: number;
  dailyQuota: number;
}

interface ConsumerUsageEntry {
  date: string;
  endpoint: string;
  statusClass: '2xx' | '3xx' | '4xx' | '5xx';
  requestCount: number;
}

export interface ApiConsumerRepository {
  issue(ownerAccountId: string, issue: ApiConsumerIssue, key: GeneratedKey): Promise<ApiConsumer>;
  list(ownerAccountId: string): Promise<ApiConsumer[]>;
  rotate(ownerAccountId: string, consumerId: string, key: GeneratedKey): Promise<ApiConsumer>;
  revoke(ownerAccountId: string, consumerId: string, keyId: string): Promise<void>;
  findActiveConsumer(keyHash: string): Promise<ActiveConsumer | null>;
  consumeRateLimit(
    consumerId: string,
    limit: number,
    at: Date,
  ): Promise<{ allowed: boolean; used: number; resetAt: Date }>;
  consumeDailyQuota(consumerId: string, quota: number): Promise<{ allowed: boolean; used: number }>;
  recordUsage?(input: {
    consumerId: string;
    keyId: string;
    endpoint: string;
    statusClass: '2xx' | '3xx' | '4xx' | '5xx';
    at: Date;
  }): Promise<void>;
  listUsage?(
    consumerId: string,
    query: { from: string; to: string; limit: number },
  ): Promise<{ totalRequests: number; entries: ConsumerUsageEntry[] }>;
}

interface GeneratedKey {
  raw: string;
  prefix: string;
  hash: string;
}

export function hashApiKey(rawKey: string): string {
  return createHash('sha256').update(rawKey).digest('hex');
}

function mapConsumer(row: ConsumerRow, keys: KeyRow[]): ApiConsumer {
  return {
    id: row.id,
    name: row.name,
    rateLimitPerMinute: row.rateLimitPerMinute,
    dailyQuota: row.dailyQuota,
    createdAt: row.createdAt.toISOString(),
    keys: keys.map((key) => ({
      id: key.id,
      prefix: key.prefix,
      createdAt: key.createdAt.toISOString(),
      revokedAt: key.revokedAt?.toISOString() ?? null,
    })),
  };
}

async function readConsumer(
  executor: QueryExecutor,
  consumerId: string,
): Promise<ApiConsumer | null> {
  const consumers = await executeQuery<ConsumerRow>(
    executor,
    `SELECT api_consumer_id::text AS id, name,
      rate_limit_per_minute AS "rateLimitPerMinute", daily_quota AS "dailyQuota", created_at AS "createdAt"
     FROM api_consumer WHERE api_consumer_id = $1`,
    [consumerId],
  );
  const consumer = consumers.rows[0];
  if (!consumer) return null;
  const keys = await executeQuery<KeyRow>(
    executor,
    `SELECT api_consumer_key_id::text AS id, api_consumer_id::text AS "consumerId",
      key_prefix AS prefix, created_at AS "createdAt", revoked_at AS "revokedAt"
     FROM api_consumer_key WHERE api_consumer_id = $1 ORDER BY api_consumer_key_id`,
    [consumerId],
  );
  return mapConsumer(consumer, keys.rows);
}

export function createApiConsumerRepository(pool: Pool = getDatabasePool()): ApiConsumerRepository {
  return {
    async issue(ownerAccountId, issue, key) {
      return withTransaction(pool, async (client) => {
        const inserted = await executeQuery<ConsumerRow>(
          client,
          `INSERT INTO api_consumer (owner_app_user_id, name, rate_limit_per_minute, daily_quota)
           VALUES ($1, $2, $3, $4)
           RETURNING api_consumer_id::text AS id, name, rate_limit_per_minute AS "rateLimitPerMinute",
             daily_quota AS "dailyQuota", created_at AS "createdAt"`,
          [ownerAccountId, issue.name, issue.rateLimitPerMinute, issue.dailyQuota],
        );
        const consumer = inserted.rows[0]!;
        await executeQuery(
          client,
          `INSERT INTO api_consumer_key (api_consumer_id, key_prefix, key_hash) VALUES ($1, $2, $3)`,
          [consumer.id, key.prefix, key.hash],
        );
        return (await readConsumer(client, consumer.id))!;
      });
    },
    async list(ownerAccountId) {
      const rows = await executeQuery<{ id: string }>(
        pool,
        `SELECT api_consumer_id::text AS id FROM api_consumer
         WHERE owner_app_user_id = $1 ORDER BY api_consumer_id`,
        [ownerAccountId],
      );
      return Promise.all(
        rows.rows.map((row) => readConsumer(pool, row.id).then((consumer) => consumer!)),
      );
    },
    async rotate(ownerAccountId, consumerId, key) {
      return withTransaction(pool, async (client) => {
        const owned = await executeQuery<{ id: string }>(
          client,
          `SELECT api_consumer_id::text AS id FROM api_consumer
           WHERE api_consumer_id = $1 AND owner_app_user_id = $2 FOR UPDATE`,
          [consumerId, ownerAccountId],
        );
        if (!owned.rows[0]) throw new ApiConsumerNotFoundError();
        await executeQuery(
          client,
          `UPDATE api_consumer_key SET revoked_at = now()
          WHERE api_consumer_id = $1 AND revoked_at IS NULL`,
          [consumerId],
        );
        await executeQuery(
          client,
          `INSERT INTO api_consumer_key (api_consumer_id, key_prefix, key_hash)
          VALUES ($1, $2, $3)`,
          [consumerId, key.prefix, key.hash],
        );
        return (await readConsumer(client, consumerId))!;
      });
    },
    async revoke(ownerAccountId, consumerId, keyId) {
      const result = await executeQuery(
        pool,
        `UPDATE api_consumer_key SET revoked_at = now()
         WHERE api_consumer_key_id = $1 AND revoked_at IS NULL
           AND api_consumer_id = $2 AND EXISTS (
             SELECT 1 FROM api_consumer WHERE api_consumer_id = $2 AND owner_app_user_id = $3
           )`,
        [keyId, consumerId, ownerAccountId],
      );
      if (result.rowCount !== 1) throw new ApiConsumerNotFoundError();
    },
    async findActiveConsumer(keyHash) {
      const result = await executeQuery<ActiveConsumer>(
        pool,
        `SELECT consumer.api_consumer_id::text AS "consumerId",
          key.api_consumer_key_id::text AS "keyId",
          consumer.rate_limit_per_minute AS "rateLimitPerMinute", consumer.daily_quota AS "dailyQuota"
         FROM api_consumer_key key
         JOIN api_consumer consumer ON consumer.api_consumer_id = key.api_consumer_id
         WHERE key.key_hash = $1 AND key.revoked_at IS NULL`,
        [keyHash],
      );
      return result.rows[0] ?? null;
    },
    async consumeRateLimit(consumerId, limit, at) {
      const result = await executeQuery<{ requestCount: number; windowStart: Date }>(
        pool,
        `WITH current_window AS (
           SELECT date_trunc('minute', $3::timestamptz) AS window_start
         )
         INSERT INTO api_consumer_minute_usage (api_consumer_id, window_start, request_count)
         SELECT $1, window_start, 1 FROM current_window
         ON CONFLICT (api_consumer_id, window_start) DO UPDATE
           SET request_count = api_consumer_minute_usage.request_count + 1
           WHERE api_consumer_minute_usage.request_count < $2
         RETURNING request_count AS "requestCount", window_start AS "windowStart"`,
        [consumerId, limit, at],
      );
      const usage = result.rows[0];
      if (!usage) {
        const windowStart = new Date(at);
        windowStart.setUTCSeconds(0, 0);
        return {
          allowed: false,
          used: limit,
          resetAt: new Date(windowStart.getTime() + 60_000),
        };
      }
      return {
        allowed: true,
        used: usage.requestCount,
        resetAt: new Date(usage.windowStart.getTime() + 60_000),
      };
    },
    async consumeDailyQuota(consumerId, quota) {
      const result = await executeQuery<{ requestCount: number }>(
        pool,
        `INSERT INTO api_consumer_daily_usage (api_consumer_id, usage_date, request_count)
         VALUES ($1, CURRENT_DATE, 1)
         ON CONFLICT (api_consumer_id, usage_date) DO UPDATE
           SET request_count = api_consumer_daily_usage.request_count + 1
           WHERE api_consumer_daily_usage.request_count < $2
         RETURNING request_count AS "requestCount"`,
        [consumerId, quota],
      );
      const used = result.rows[0]?.requestCount;
      return used === undefined ? { allowed: false, used: quota } : { allowed: true, used };
    },
    async recordUsage({ consumerId, keyId, endpoint, statusClass, at }) {
      await executeQuery(
        pool,
        `INSERT INTO api_consumer_request_usage
          (api_consumer_id, api_consumer_key_id, occurred_at, endpoint, status_class)
         VALUES ($1, $2, $3, $4, $5)`,
        [consumerId, keyId, at, endpoint, statusClass],
      );
    },
    async listUsage(consumerId, query) {
      const total = await executeQuery<{ totalRequests: number }>(
        pool,
        `SELECT count(*)::int AS "totalRequests"
         FROM api_consumer_request_usage
         WHERE api_consumer_id = $1 AND occurred_at >= $2::date
           AND occurred_at < ($3::date + INTERVAL '1 day')`,
        [consumerId, query.from, query.to],
      );
      const entries = await executeQuery<ConsumerUsageEntry>(
        pool,
        `SELECT occurred_at::date::text AS date, endpoint,
          status_class AS "statusClass", count(*)::int AS "requestCount"
         FROM api_consumer_request_usage
         WHERE api_consumer_id = $1 AND occurred_at >= $2::date
           AND occurred_at < ($3::date + INTERVAL '1 day')
         GROUP BY occurred_at::date, endpoint, status_class
         ORDER BY occurred_at::date DESC, endpoint ASC, status_class ASC
         LIMIT $4`,
        [consumerId, query.from, query.to, query.limit],
      );
      return { totalRequests: total.rows[0]?.totalRequests ?? 0, entries: entries.rows };
    },
  };
}

/** Avoid opening the application pool for routes that do not use consumer keys. */
export function createLazyApiConsumerRepository(): ApiConsumerRepository {
  let repository: ApiConsumerRepository | undefined;
  const resolved = () => (repository ??= createApiConsumerRepository());
  return {
    issue: (...args) => resolved().issue(...args),
    list: (...args) => resolved().list(...args),
    rotate: (...args) => resolved().rotate(...args),
    revoke: (...args) => resolved().revoke(...args),
    findActiveConsumer: (...args) => resolved().findActiveConsumer(...args),
    consumeRateLimit: (...args) => resolved().consumeRateLimit(...args),
    consumeDailyQuota: (...args) => resolved().consumeDailyQuota(...args),
    recordUsage: (...args) => resolved().recordUsage!(...args),
    listUsage: (...args) => resolved().listUsage!(...args),
  };
}

export class ApiConsumerNotFoundError extends Error {
  constructor() {
    super('The API consumer or key was not found.');
  }
}

import { Router } from 'express';

import type { VerifyAccessToken } from '../../auth/supabase-auth';
import { requireAuthentication } from '../../middleware/require-authentication';
import { requireAdministrator } from '../../middleware/require-authorization';
import type { SynchronizeAccount } from '../accounts/account.service';
import {
  createApiConsumerIssueController,
  createApiConsumerListController,
  createApiConsumerRevokeController,
  createApiConsumerRotateController,
} from './api-consumer.controller';
import type { ApiConsumerService } from './api-consumer.service';

export function createApiConsumerRouter(
  verify: VerifyAccessToken,
  synchronize: SynchronizeAccount,
  service: ApiConsumerService,
): Router {
  const router = Router();
  const authenticate = requireAuthentication(verify, synchronize);
  const authorize = requireAdministrator();
  router.get(
    '/admin/api-consumers',
    authenticate,
    authorize,
    createApiConsumerListController(service),
  );
  router.post(
    '/admin/api-consumers',
    authenticate,
    authorize,
    createApiConsumerIssueController(service),
  );
  router.post(
    '/admin/api-consumers/:consumerId/keys/rotate',
    authenticate,
    authorize,
    createApiConsumerRotateController(service),
  );
  router.delete(
    '/admin/api-consumers/:consumerId/keys/:keyId',
    authenticate,
    authorize,
    createApiConsumerRevokeController(service),
  );
  return router;
}

import {
  apiConsumerIssueResponseSchema,
  apiConsumerIssueSchema,
  apiConsumerListResponseSchema,
  apiConsumerRotateResponseSchema,
} from '@sport-analytics/contracts';
import type { RequestHandler, Response } from 'express';

import type { ApplicationAccount } from '../accounts/account';
import { ApiConsumerNotFoundError } from './api-consumer.repository';
import type { ApiConsumerService } from './api-consumer.service';

function account(response: Response): ApplicationAccount {
  const authenticated = response.locals.authenticatedAccount as ApplicationAccount | undefined;
  if (!authenticated) throw new Error('API consumer controller requires an authenticated account');
  return authenticated;
}

function validId(value: string | undefined): value is string {
  return value !== undefined && /^\d+$/.test(value);
}

function validationError(response: Response, message: string): void {
  response.status(422).json({ error: { code: 'VALIDATION_FAILED', message } });
}

export function createApiConsumerIssueController(service: ApiConsumerService): RequestHandler {
  return (request, response, next) => {
    const parsed = apiConsumerIssueSchema.safeParse(request.body);
    if (!parsed.success) {
      validationError(response, 'The API consumer request is invalid.');
      return;
    }
    void service
      .issue(account(response), parsed.data)
      .then((result) => {
        response.status(201).json(apiConsumerIssueResponseSchema.parse({ data: result }));
      })
      .catch(next);
  };
}

export function createApiConsumerListController(service: ApiConsumerService): RequestHandler {
  return (_request, response, next) => {
    void service
      .list(account(response))
      .then((consumers) => {
        response.status(200).json(apiConsumerListResponseSchema.parse({ data: { consumers } }));
      })
      .catch(next);
  };
}

export function createApiConsumerRotateController(service: ApiConsumerService): RequestHandler {
  return (request, response, next) => {
    if (!validId(request.params.consumerId)) {
      validationError(response, 'The API consumer identifier is invalid.');
      return;
    }
    void service
      .rotate(account(response), request.params.consumerId)
      .then((result) => {
        response.status(200).json(apiConsumerRotateResponseSchema.parse({ data: result }));
      })
      .catch((error: unknown) => {
        if (error instanceof ApiConsumerNotFoundError) {
          response
            .status(404)
            .json({ error: { code: 'API_CONSUMER_NOT_FOUND', message: error.message } });
          return;
        }
        next(error);
      });
  };
}

export function createApiConsumerRevokeController(service: ApiConsumerService): RequestHandler {
  return (request, response, next) => {
    if (!validId(request.params.consumerId) || !validId(request.params.keyId)) {
      validationError(response, 'The API consumer key identifier is invalid.');
      return;
    }
    void service
      .revoke(account(response), request.params.consumerId, request.params.keyId)
      .then(() => {
        response.status(204).end();
      })
      .catch((error: unknown) => {
        if (error instanceof ApiConsumerNotFoundError) {
          response
            .status(404)
            .json({ error: { code: 'API_CONSUMER_KEY_NOT_FOUND', message: error.message } });
          return;
        }
        next(error);
      });
  };
}

import type { ApiConsumer, ApiConsumerIssue } from '@sport-analytics/contracts';
import { randomBytes } from 'node:crypto';

import type { ApplicationAccount } from '../accounts/account';
import {
  createApiConsumerRepository,
  hashApiKey,
  type ApiConsumerRepository,
} from './api-consumer.repository';

export interface ApiConsumerService {
  issue(
    owner: ApplicationAccount,
    issue: ApiConsumerIssue,
  ): Promise<ApiConsumer & { apiKey: string }>;
  list(owner: ApplicationAccount): Promise<ApiConsumer[]>;
  rotate(owner: ApplicationAccount, consumerId: string): Promise<ApiConsumer & { apiKey: string }>;
  revoke(owner: ApplicationAccount, consumerId: string, keyId: string): Promise<void>;
}

function generateKey() {
  const raw = `sat_live_${randomBytes(32).toString('base64url')}`;
  return { raw, prefix: raw.slice(0, 17), hash: hashApiKey(raw) };
}

export function createApiConsumerService(
  repository: ApiConsumerRepository = createApiConsumerRepository(),
): ApiConsumerService {
  return {
    async issue(owner, issue) {
      const key = generateKey();
      return { ...(await repository.issue(owner.accountId, issue, key)), apiKey: key.raw };
    },
    async list(owner) {
      return repository.list(owner.accountId);
    },
    async rotate(owner, consumerId) {
      const key = generateKey();
      return { ...(await repository.rotate(owner.accountId, consumerId, key)), apiKey: key.raw };
    },
    async revoke(owner, consumerId, keyId) {
      await repository.revoke(owner.accountId, consumerId, keyId);
    },
  };
}

