          requestCount: 1,
        },
      ],
    });
    const telemetry = await executeQuery<{ rawKey: string | null; query: string | null }>(
      pool,
      `SELECT null::text AS "rawKey", null::text AS query FROM api_consumer_request_usage
       WHERE api_consumer_id = $1`,
