        approved: true,
        competitionIds: ['7', '7'],
      }).success,
    ).toBe(false);
    expect(
      administratorSubmitterAccessUpdateSchema.safeParse({
        approved: true,
        competitionIds: ['7'],
      }).success,
    ).toBe(true);
  });

