  });

  test('rejects a response without the approval state', () => {
    const result = currentUserProfileResponseSchema.safeParse({
      user: {
        id: '42',
        subject: 'supabase-user-123',
        displayName: 'Example User',
        role: 'viewer',
        requestedCompetition: null,
